repo.fixtures.py:
"""Fixture records."""


class Fixture:
    def __init__(self, club, goals):
        self.club = club
        self.goals = goals

    def __repr__(self):
        return "Fixture(%r, %r)" % (self.club, self.goals)


ROWS = [('rovers', 18), ('united', 54), ('united', 15), ('united', 40), ('rovers', 42)]


def load_fixtures():
    """Yield the stored fixtures one at a time."""
    for club, goals in ROWS:
        yield Fixture(club, goals)

repo.parsing.py:
"""Parsing fixtures from text."""
from fixtures import Fixture


def _parse_line(line):
    club, goals = line.split(",")
    return Fixture(club.strip(), int(goals))


def parse_fixtures(text):
    """Parse lines of 'club,goals' into Fixture records. Blank lines are skipped."""
    out = []
    line = ""
    for ch in text:
        if ch == "\n":
            if line.strip():
                out.append(_parse_line(line))
            line = ""
        else:
            line += ch
    return out


def group_by_club(fixtures):
    """Return a dict from club to the list of fixtures with that club."""
    groups = {}
    for x in fixtures:
        groups.setdefault(x.club, []).append(x)
    return groups


def largest_goals(fixtures):
    """Return the largest goals, or None when there are no fixtures."""
    values = [x.goals for x in fixtures]
    return max(values) if values else None
